class AdminLoginPage extends StatefulWidget { const AdminLoginPage({super.key}); @override State<AdminLoginPage> createState() => _AdminLoginPageState(); }
class _AdminLoginPageState extends State<AdminLoginPage> {
  final email = TextEditingController(); final password = TextEditingController(); String? error; bool loading = false;
  Future<void> submit() async { setState(() { loading = true; error = null; }); try { await AdminApi.login(email.text.trim(), password.text); if (mounted) Navigator.pushReplacementNamed(context, '/admin/dashboard'); } catch (e) { if (mounted) setState(() => error = e.toString().replaceFirst('Exception: ', '')); } finally { if (mounted) setState(() => loading = false); } }
  @override Widget build(BuildContext context) { final t = AppTheme.of(context); return Scaffold(backgroundColor: t.background, body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 400), child: Card(color: t.card, child: Padding(padding: const EdgeInsets.all(AppSpacing.xl), child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [Text('Admin access', style: t.heading), const SizedBox(height: AppSpacing.sm), Text('Sign in to manage portfolio content.', style: t.body), const SizedBox(height: AppSpacing.lg), TextField(controller: email, decoration: const InputDecoration(labelText: 'Email')), const SizedBox(height: AppSpacing.md), TextField(controller: password, obscureText: true, onSubmitted: (_) => submit(), decoration: const InputDecoration(labelText: 'Password')), if (error != null) Padding(padding: const EdgeInsets.only(top: AppSpacing.sm), child: Text(error!, style: const TextStyle(color: AppColors.danger))), const SizedBox(height: AppSpacing.lg), FilledButton(onPressed: loading ? null : submit, child: Text(loading ? 'Signing in…' : 'Sign in'))])))))); }
}

class AdminPanel extends StatefulWidget { final String section; const AdminPanel({super.key, required this.section}); @override State<AdminPanel> createState() => _AdminPanelState(); }
class _AdminPanelState extends State<AdminPanel> {
  Future<dynamic>? data;
  String get endpoint => switch (widget.section) { 'dashboard' || 'analytics' => '/api/admin/analytics/overview', 'messages' => '/api/admin/submissions', 'projects' => '/api/admin/projects', 'journey' => '/api/admin/journey', 'skills' => '/api/admin/skills', 'about' => '/api/admin/about', _ => '/api/admin/analytics/overview' };
  @override void initState() { super.initState(); data = AdminSession.active ? AdminApi.get(endpoint) : null; }
  void refresh() => setState(() => data = AdminApi.get(endpoint));
  Future<void> action(String method, String path, {Map<String, dynamic>? body}) async { try { await AdminApi.send(method, path, body: body); if (mounted) refresh(); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } }
  Future<void> jsonEditor({Map<String, dynamic>? initial, String? path, String method = 'POST'}) async {
    final controller = TextEditingController(text: const JsonEncoder.withIndent('  ').convert(initial ?? <String, dynamic>{}));
    await showDialog<void>(context: context, builder: (dialog) => AlertDialog(title: Text(path == null ? 'Create ${widget.section}' : 'Edit ${widget.section}'), content: SizedBox(width: 620, child: TextField(controller: controller, minLines: 14, maxLines: 20, style: const TextStyle(fontFamily: 'monospace'), decoration: const InputDecoration(border: OutlineInputBorder()))), actions: [TextButton(onPressed: () => Navigator.pop(dialog), child: const Text('Cancel')), FilledButton(onPressed: () async { try { final value = jsonDecode(controller.text); if (value is! Map<String, dynamic>) throw const FormatException('JSON object required'); await action(method, path ?? endpoint, body: value); if (dialog.mounted) Navigator.pop(dialog); } catch (e) { if (dialog.mounted) ScaffoldMessenger.of(dialog).showSnackBar(SnackBar(content: Text('Invalid data: $e'))); } }, child: const Text('Save'))]));
  }
  List<Map<String, dynamic>> items(dynamic value) { if (value is Map<String, dynamic>) { final candidate = value['items'] ?? value['submissions']; if (candidate is List) return candidate.whereType<Map<String, dynamic>>().toList(); } return value is List ? value.whereType<Map<String, dynamic>>().toList() : const []; }
  @override Widget build(BuildContext context) { if (!AdminSession.active) { WidgetsBinding.instance.addPostFrameCallback((_) => Navigator.pushReplacementNamed(context, '/admin/login')); return const SizedBox(); } final t = AppTheme.of(context); const sections = ['dashboard', 'projects', 'journey', 'skills', 'about', 'messages', 'analytics']; return Scaffold(backgroundColor: t.background, appBar: AppBar(title: const Text('Portfolio admin'), actions: [IconButton(onPressed: refresh, icon: const Icon(Icons.refresh)), TextButton(onPressed: () { AdminSession.clear(); Navigator.pushReplacementNamed(context, '/admin/login'); }, child: const Text('Sign out'))]), body: Row(children: [NavigationRail(selectedIndex: sections.indexOf(widget.section), labelType: NavigationRailLabelType.all, onDestinationSelected: (i) => Navigator.pushReplacementNamed(context, '/admin/${sections[i]}'), destinations: sections.map((s) => NavigationRailDestination(icon: const Icon(Icons.circle_outlined), selectedIcon: const Icon(Icons.circle), label: Text(s[0].toUpperCase() + s.substring(1)))).toList()), Expanded(child: Padding(padding: const EdgeInsets.all(AppSpacing.xl), child: FutureBuilder<dynamic>(future: data, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return Center(child: Text(snapshot.error.toString())); final records = items(snapshot.data); return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Text(widget.section[0].toUpperCase() + widget.section.substring(1), style: t.heading), const Spacer(), if (['projects','journey','skills'].contains(widget.section)) FilledButton.icon(onPressed: () => jsonEditor(), icon: const Icon(Icons.add), label: const Text('Create draft'))]), const SizedBox(height: AppSpacing.lg), Expanded(child: records.isEmpty ? SingleChildScrollView(child: SelectableText(const JsonEncoder.withIndent('  ').convert(snapshot.data), style: t.body.copyWith(fontFamily: 'monospace'))) : ListView.separated(itemCount: records.length, separatorBuilder: (_, __) => const SizedBox(height: 8), itemBuilder: (_, index) { final item = records[index]; final id = item['id']; final title = item['title'] ?? item['name'] ?? item['email'] ?? 'Record #$id'; final base = widget.section == 'journey' ? '/api/admin/journey/$id' : '/api/admin/${widget.section}/$id'; return Card(child: ListTile(title: Text('$title'), subtitle: Text('Status: ${item['status'] ?? 'active'} · Version: ${item['version'] ?? '—'}'), onTap: () => jsonEditor(initial: item, path: base, method: 'PUT'), trailing: Wrap(spacing: 4, children: [if (['projects','journey','skills'].contains(widget.section)) IconButton(tooltip: 'Publish', onPressed: () => action('POST', '$base/publish'), icon: const Icon(Icons.publish)), if (['projects','journey','skills'].contains(widget.section)) IconButton(tooltip: 'Versions', onPressed: () async { final versions = await AdminApi.get('$base/versions'); if (mounted) jsonEditor(initial: {'versions': versions}); }, icon: const Icon(Icons.history)), IconButton(tooltip: 'Delete / archive', onPressed: () => action('DELETE', base), icon: const Icon(Icons.delete_outline))]))); }))]); })))])); }
}
